text:
/* Scoped motion and pseudo-elements shared by all footer variants. */
[data-site-footer][data-footer-variant] .footer-link {
  transition: color 180ms ease;
  text-decoration: none;
}
[data-site-footer][data-footer-variant] .footer-link::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  bottom: var(--footer-underline-bottom, -4px);
  height: 1px;
  background: var(--footer-accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 220ms ease;
  pointer-events: none;
}
[data-site-footer][data-footer-variant] .footer-link:focus-visible {
  color: var(--footer-text);
}
[data-site-footer][data-footer-variant] .footer-link:focus-visible::after {
  transform: scaleX(1);
}
@media (hover: hover) and (pointer: fine) {
  [data-site-footer][data-footer-variant] .footer-link:hover {
    color: var(--footer-text);
    text-decoration: none;
  }
  [data-site-footer][data-footer-variant] .footer-link:hover::after {
    transform: scaleX(1);
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-site-footer][data-footer-variant] .footer-link,
  [data-site-footer][data-footer-variant] .footer-link::after {
    transition: none;
  }
}
